<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>🧬 Conway's Game of Life</title>
<style>
  :root {
    --bg: #0d1117;
    --panel: #161b22;
    --accent: #58a6ff;
    --alive: #3fb950;
    --grid-line: #21262d;
    --text: #c9d1d9;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: radial-gradient(circle at 50% -10%, #16203a, var(--bg));
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    color: var(--text);
    padding: 24px;
  }
  .stage {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
  }
  h1 {
    margin: 0;
    font-size: 1.5rem;
    letter-spacing: 0.5px;
    background: linear-gradient(90deg, #58a6ff, #3fb950);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
  #life {
    background: var(--panel);
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.55), inset 0 0 0 1px #21262d;
    cursor: crosshair;
    touch-action: none;
    display: block;
  }
  .controls {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    font: inherit;
    font-weight: 600;
    color: var(--text);
    background: #21262d;
    border: 1px solid #30363d;
    border-radius: 8px;
    padding: 10px 16px;
    cursor: pointer;
    transition: transform 0.08s ease, background 0.15s ease;
  }
  button:hover { background: #30363d; }
  button:active { transform: translateY(1px) scale(0.97); }
  #play { background: var(--alive); color: #06210f; border-color: #2ea043; }
  #play:hover { background: #2ea043; }
  #play.running { background: #d29922; color: #2a1c00; border-color: #bb8009; }
  .stats {
    font-size: 0.85rem;
    color: #8b949e;
    display: flex;
    gap: 16px;
  }
  .stats b { color: var(--accent); }
</style>
</head>
<body>
  <div class="stage">
    <h1>🧬 Conway's Game of Life</h1>
    <canvas id="life"></canvas>
    <div class="controls">
      <button id="step">⏭ Step</button>
      <button id="play">▶ Play</button>
      <button id="random">🎲 Random</button>
      <button id="clear">🧹 Clear</button>
    </div>
    <div class="stats">
      <span>Gen <b id="gen">0</b></span>
      <span>Alive <b id="pop">0</b></span>
    </div>
  </div>

<script>
(function () {
  "use strict";

  const CELL = 10;          // pixels per cell
  const W = 50;             // grid width in cells (>= 40)
  const H = 50;             // grid height in cells (>= 40)
  const canvas = document.getElementById("life");
  const ctx = canvas.getContext("2d");

  // Canvas is >= 400 x 400 CSS pixels.
  canvas.width = W * CELL;   // 500
  canvas.height = H * CELL;  // 500
  canvas.style.width = canvas.width + "px";
  canvas.style.height = canvas.height + "px";

  const grid = new Uint8Array(W * H);
  const idx = (x, y) => y * W + x;

  function get(x, y) {
    if (x < 0 || y < 0 || x >= W || y >= H) return 0; // dead edges
    return grid[idx(x, y)];
  }

  function set(x, y, v) {
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    grid[idx(x, y)] = v ? 1 : 0;
  }

  // Advance exactly one generation using SIMULTANEOUS update.
  function step() {
    const next = new Uint8Array(W * H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        let n = 0;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            n += get(x + dx, y + dy);
          }
        }
        const alive = grid[idx(x, y)];
        next[idx(x, y)] = alive ? (n === 2 || n === 3 ? 1 : 0) : (n === 3 ? 1 : 0);
      }
    }
    grid.set(next);          // apply all at once
    generation++;
    draw();
  }

  function clear() {
    grid.fill(0);
    generation = 0;
    draw();
  }

  function randomize() {
    for (let i = 0; i < grid.length; i++) grid[i] = Math.random() < 0.28 ? 1 : 0;
    generation = 0;
    draw();
  }

  // ---------- rendering ----------
  function roundRect(c, x, y, w, h, r) {
    c.beginPath();
    c.moveTo(x + r, y);
    c.arcTo(x + w, y, x + w, y + h, r);
    c.arcTo(x + w, y + h, x, y + h, r);
    c.arcTo(x, y + h, x, y, r);
    c.arcTo(x, y, x + w, y, r);
    c.closePath();
  }

  function draw() {
    ctx.fillStyle = "#161b22";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = "#21262d";
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= W; x++) {
      ctx.moveTo(x * CELL + 0.5, 0);
      ctx.lineTo(x * CELL + 0.5, H * CELL);
    }
    for (let y = 0; y <= H; y++) {
      ctx.moveTo(0, y * CELL + 0.5);
      ctx.lineTo(W * CELL, y * CELL + 0.5);
    }
    ctx.stroke();

    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (grid[idx(x, y)]) {
          const px = x * CELL;
          const py = y * CELL;
          ctx.fillStyle = "#3fb950";
          roundRect(ctx, px + 1, py + 1, CELL - 2, CELL - 2, 2);
          ctx.fill();
        }
      }
    }

    document.getElementById("gen").textContent = generation;
    let pop = 0;
    for (let i = 0; i < grid.length; i++) pop += grid[i];
    document.getElementById("pop").textContent = pop;
  }

  // ---------- painting via click / drag ----------
  let painting = false;
  let paintValue = 1;

  function cellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const px = (e.clientX - rect.left) * scaleX;
    const py = (e.clientY - rect.top) * scaleY;
    return [Math.floor(px / CELL), Math.floor(py / CELL)];
  }

  function paint(e) {
    const x = cellFromEvent(e)[0];
    const y = cellFromEvent(e)[1];
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    set(x, y, paintValue);
    draw();
  }

  canvas.addEventListener("pointerdown", function (e) {
    e.preventDefault();
    const [x, y] = cellFromEvent(e);
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    paintValue = get(x, y) ? 0 : 1; // first click sets the paint mode
    painting = true;
    set(x, y, paintValue);
    draw();
    canvas.setPointerCapture(e.pointerId);
  });

  canvas.addEventListener("pointermove", function (e) {
    if (!painting) return;
    e.preventDefault();
    const [x, y] = cellFromEvent(e);
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    set(x, y, paintValue);
    draw();
  });

  window.addEventListener("pointerup", function () { painting = false; });

  // ---------- controls / auto-run ----------
  const stepBtn = document.getElementById("step");
  const playBtn = document.getElementById("play");

  let running = false;
  let lastTime = 0;
  let acc = 0;
  const STEP_MS = 120;

  function start() {
    if (running) return;
    running = true;
    playBtn.textContent = "⏸ Pause";
    playBtn.classList.add("running");
    lastTime = performance.now();
    requestAnimationFrame(loop);
  }
  function stop() {
    running = false;
    playBtn.textContent = "▶ Play";
    playBtn.classList.remove("running");
  }
  function togglePlay() { running ? stop() : start(); }

  function loop(now) {
    if (!running) return;
    acc += now - lastTime;
    lastTime = now;
    while (acc >= STEP_MS) { step(); acc -= STEP_MS; }
    requestAnimationFrame(loop);
  }

  stepBtn.addEventListener("click", function () { stop(); step(); });
  playBtn.addEventListener("click", togglePlay);
  document.getElementById("random").addEventListener("click", function () { stop(); randomize(); });
  document.getElementById("clear").addEventListener("click", function () { stop(); clear(); });

  // fun keyboard shortcuts
  window.addEventListener("keydown", function (e) {
    if (e.target && (e.target.tagName === "BUTTON")) return;
    if (e.code === "Space") { e.preventDefault(); togglePlay(); }
    else if (e.key.toLowerCase() === "s") { stop(); step(); }
    else if (e.key.toLowerCase() === "r") { stop(); randomize(); }
    else if (e.key.toLowerCase() === "c") { stop(); clear(); }
  });

  // ---------- public API for grading ----------
  window.life = {
    w: W,
    h: H,
    get: get,
    set: set,
    step: step,
    clear: clear,
  };
  Object.defineProperty(window.life, "grid", {
    get: function () { return grid; }, configurable: true
  });

  draw();
})();
</script>
</body>
</html>
